package glitch

import data.glitch_lib

world_readable_permissions := {"0755", "0775", "0777", "755", "775", "777", "og+w", "a+w", "777", "ugo+rwx"}

world_writable_permissions := {"0777", "777", "a+w", "og+w", "ugo+w", "777"}

check_insecure_permission(value) {
    value.ir_type == "String"
    regex.match("(?:^0?777$)|(?:^0?775$)|(?:^0?755$)|(?:(?:^|(?:ugo)|o|a)\\+[rwx]{3})", value.value)
} else {
    value.ir_type == "Integer"
    bits := [0o777, 0o775, 0o755, 777, 775, 755]
    value.value == bits[_]
}

check_missing_authentication(node) {
    not has_authentication_attribute(node)
}

has_authentication_attribute(node) {
    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]
    regex.match("(?i)auth", attr.name)
}

check_missing_authorization(node) {
    not has_authorization_attribute(node)
}

has_authorization_attribute(node) {
    attrs := glitch_lib.all_attributes(node)
